<?php

declare(strict_types=1);
require dirname(__DIR__) . '/config/bootstrap.php';
use App\Auth;
use App\Database;
$userId=Auth::requireLogin();
$pdo=Database::connection();
$statusFilter=trim((string)($_GET['status']??''));
$search=trim((string)($_GET['q']??''));
$sql="SELECT o.*,s.name service,s.provider_type FROM orders o JOIN services s ON s.id=o.service_id WHERE o.user_id=:id";
$params=[':id'=>$userId];
if($statusFilter!==''){$sql.=' AND o.status=:status';$params[':status']=$statusFilter;}
if($search!==''){$sql.=' AND (CAST(o.id AS CHAR)=:search OR s.name LIKE :search_like OR o.provider_order_id LIKE :search_like)';$params[':search']=$search;$params[':search_like']='%'.$search.'%';}
$sql.=' ORDER BY o.id DESC LIMIT 100';
$stmt=$pdo->prepare($sql);$stmt->execute($params);$orders=$stmt->fetchAll();
$statuses=$pdo->prepare('SELECT DISTINCT status FROM orders WHERE user_id=:id ORDER BY status');$statuses->execute([':id'=>$userId]);$statusOptions=$statuses->fetchAll(PDO::FETCH_COLUMN);
$currency=(string)env('CURRENCY','NGN');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Orders | SMM Panel</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><style>.status-dot{width:9px;height:9px;border-radius:50%;display:inline-block}.order-row{cursor:pointer}.progress{height:8px}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand fw-semibold" href="/dashboard.php">SMM Panel</a><div class="d-flex gap-2"><a class="btn btn-outline-light btn-sm" href="/services.php">Services</a><a class="btn btn-primary btn-sm" href="/order.php">New Order</a></div></div></nav><main class="container py-4 py-lg-5"><div class="d-flex flex-column flex-lg-row justify-content-between gap-3 mb-4"><div><div class="text-primary small fw-semibold text-uppercase">Order centre</div><h1 class="h2 mb-1">My Orders</h1><p class="text-muted mb-0">Track fulfilment progress and provider updates in real time.</p></div><a class="btn btn-outline-secondary align-self-start" href="/dashboard.php">Dashboard</a></div><form class="card border-0 shadow-sm mb-4" method="get"><div class="card-body"><div class="row g-2"><div class="col-md-7"><input class="form-control" name="q" value="<?=htmlspecialchars($search)?>" placeholder="Search order ID, service or provider ID"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach($statusOptions as $status):?><option value="<?=htmlspecialchars($status)?>" <?=$statusFilter===$status?'selected':''?>><?=htmlspecialchars(ucwords(str_replace('_',' ',$status)))?></option><?php endforeach;?></select></div><div class="col-md-2 d-grid"><button class="btn btn-dark">Filter</button></div></div></div></form><div class="row g-3" id="ordersList"><?php foreach($orders as $o):$status=strtolower((string)$o['status']);$terminal=in_array($status,['completed','partial','cancelled','failed','refunded'],true);$quantity=max(1,(int)$o['quantity']);$remains=$o['remains']!==null?(int)$o['remains']:null;$done=$remains===null?null:max(0,min(100,(int)round((($quantity-$remains)/$quantity)*100)));?><div class="col-12"><div class="card border-0 shadow-sm order-card"><div class="card-body p-4"><div class="d-flex flex-column flex-md-row justify-content-between gap-3"><div><div class="text-muted small">Order #<?= (int)$o['id']?> · <?=htmlspecialchars($o['created_at'])?></div><h5 class="mb-1"><?=htmlspecialchars($o['service'])?></h5><div class="small text-muted"><?=htmlspecialchars($o['provider_type'])?> · Provider ID: <?=htmlspecialchars((string)($o['provider_order_id']??'Pending'))?></div></div><div class="text-md-end"><span class="badge status-badge text-bg-secondary"><?=htmlspecialchars(ucwords(str_replace('_',' ',$status)))?></span><div class="small text-muted mt-1">Last sync: <span class="last-sync"><?=htmlspecialchars((string)($o['last_synced_at']??'Not yet'))?></span></div></div></div><div class="row g-3 mt-2"><div class="col-6 col-md-3"><small class="text-muted d-block">Quantity</small><strong><?=number_format((int)$o['quantity'])?></strong></div><div class="col-6 col-md-3"><small class="text-muted d-block">Start count</small><strong class="start-count"><?=htmlspecialchars((string)($o['start_count']??'-'))?></strong></div><div class="col-6 col-md-3"><small class="text-muted d-block">Remaining</small><strong class="remains"><?=htmlspecialchars((string)($o['remains']??'-'))?></strong></div><div class="col-6 col-md-3"><small class="text-muted d-block">Charge</small><strong><?=htmlspecialchars($currency)?> <?=number_format((float)$o['charge'],2)?></strong></div></div><?php if($done!==null):?><div class="mt-3"><div class="d-flex justify-content-between small text-muted mb-1"><span>Fulfilment progress</span><span class="progress-label"><?=$done?>%</span></div><div class="progress"><div class="progress-bar progress-value" style="width:<?=$done?>%"></div></div></div><?php endif;?><div class="d-flex flex-wrap gap-2 mt-3"><button class="btn btn-outline-primary btn-sm track-btn" data-order-id="<?= (int)$o['id']?>"><i class="bi bi-broadcast me-1"></i>Live tracking</button><a class="btn btn-outline-secondary btn-sm" href="/order.php?service=<?= (int)$o['service_id']?>">Order again</a></div></div></div></div><?php endforeach;if(!$orders):?><div class="col-12"><div class="alert alert-info">No orders found. <a href="/services.php">Browse the service catalogue</a>.</div></div><?php endif;?></div></main><div class="modal fade" id="trackingModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content border-0 shadow"><div class="modal-header"><div><h5 class="modal-title" id="trackingTitle">Live order tracking</h5><div class="small text-muted" id="trackingSubtitle">Refreshing automatically</div></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div id="trackingAlert" class="alert alert-info">Loading latest provider status...</div><div class="row g-3 mb-3"><div class="col-6 col-md-3"><div class="bg-light rounded p-3"><small class="text-muted">Status</small><div class="fw-semibold" id="trackingStatus">—</div></div></div><div class="col-6 col-md-3"><div class="bg-light rounded p-3"><small class="text-muted">Quantity</small><div class="fw-semibold" id="trackingQuantity">—</div></div></div><div class="col-6 col-md-3"><div class="bg-light rounded p-3"><small class="text-muted">Start</small><div class="fw-semibold" id="trackingStart">—</div></div></div><div class="col-6 col-md-3"><div class="bg-light rounded p-3"><small class="text-muted">Remaining</small><div class="fw-semibold" id="trackingRemains">—</div></div></div></div><div class="mb-4"><div class="d-flex justify-content-between small text-muted mb-1"><span>Fulfilment</span><span id="trackingPercent">0%</span></div><div class="progress"><div id="trackingProgress" class="progress-bar" style="width:0%"></div></div></div><h6>Status history</h6><div id="trackingHistory" class="list-group list-group-flush"></div></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>
const modal=new bootstrap.Modal(document.getElementById('trackingModal'));let trackingTimer=null;let activeOrder=0;const terminal=['completed','partial','cancelled','failed','refunded'];
function setText(id,v){document.getElementById(id).textContent=v??'—'}
function render(data){const status=String(data.status||'').toLowerCase();setText('trackingStatus',status.replaceAll('_',' '));setText('trackingQuantity',Number(data.quantity||0).toLocaleString());setText('trackingStart',data.start_count==null?'—':Number(data.start_count).toLocaleString());setText('trackingRemains',data.remains==null?'—':Number(data.remains).toLocaleString());let pct=0;if(data.remains!=null&&Number(data.quantity)>0)pct=Math.max(0,Math.min(100,Math.round((Number(data.quantity)-Number(data.remains))/Number(data.quantity)*100)));document.getElementById('trackingProgress').style.width=pct+'%';setText('trackingPercent',pct+'%');setText('trackingTitle','Order #'+data.id+' · '+data.service_name);setText('trackingSubtitle',(data.provider_order_id?'Provider '+data.provider_order_id:'Waiting for provider confirmation')+' · '+(data.last_synced_at||'Not synced'));const alert=document.getElementById('trackingAlert');alert.className='alert '+(terminal.includes(status)?'alert-success':'alert-info');alert.textContent=terminal.includes(status)?'This order has reached a terminal status.':'Live provider status is being refreshed every 8 seconds.';const history=document.getElementById('trackingHistory');history.innerHTML=(data.history||[]).map(h=>`<div class="list-group-item px-0"><div class="d-flex justify-content-between"><strong>${escapeHtml(String(h.status||'').replaceAll('_',' '))}</strong><small class="text-muted">${escapeHtml(h.created_at||'')}</small></div><div class="small text-muted">Start: ${h.start_count??'—'} · Remaining: ${h.remains??'—'} · ${escapeHtml(h.source||'')}</div></div>`).join('')||'<div class="text-muted small py-2">No status history recorded yet.</div>'}
function escapeHtml(v){return v.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
async function refreshTracking(){if(!activeOrder)return;try{const r=await fetch('/api/order-tracking.php?order='+encodeURIComponent(activeOrder),{headers:{Accept:'application/json'},cache:'no-store'});const json=await r.json();if(!r.ok)throw new Error(json.error||'Refresh failed');render(json.data)}catch(e){const a=document.getElementById('trackingAlert');a.className='alert alert-warning';a.textContent='Provider status could not be refreshed right now. Automatic sync will retry.'}}
document.querySelectorAll('.track-btn').forEach(btn=>btn.addEventListener('click',()=>{activeOrder=btn.dataset.orderId;refreshTracking();modal.show();clearInterval(trackingTimer);trackingTimer=setInterval(refreshTracking,8000)}));document.getElementById('trackingModal').addEventListener('hidden.bs.modal',()=>{clearInterval(trackingTimer);trackingTimer=null;activeOrder=0});
</script></body></html>
